import Foundation

enum AppData {
    static func loadWords() -> [Word] {
        var rows:[Word]=[]; var next=1
        for name in ["gept_words","toeic_words"] {
            guard let url=Bundle.main.url(forResource:name, withExtension:"tsv"), let text=try? String(contentsOf:url, encoding:.utf8) else { continue }
            for raw in text.split(whereSeparator:\.isNewline) {
                let c=raw.split(separator:"\t", omittingEmptySubsequences:false).map(String.init)
                guard c.count>=2 else { continue }
                let en=c[0].trimmingCharacters(in:.whitespacesAndNewlines), zh=c[1].trimmingCharacters(in:.whitespacesAndNewlines)
                if en.isEmpty || zh.isEmpty || en.lowercased().contains("english") { continue }
                rows.append(Word(id:next, english:en, chinese:zh, partOfSpeech:c.count>2 ? c[2]:"", note:c.count>3 ? c[3]:"", level:c.count>4 ? c[4]:"", academic:c.count>5 ? c[5]:"", ceecLevel:c.count>6 ? c[6]:"")); next += 1
            }
        }
        return rows
    }
